  VALUES ?person { dbr:Lisbeth_Cathrine_Amalie_Rose dbr:Princess_Raiyah_bint_Hussein }
  OPTIONAL { ?person dbo:birthDate ?dboBirth. }
  OPTIONAL { ?person dbp:birthDate ?dbpBirth. }
  OPTIONAL { ?person dbp:born ?dbpBorn. }
}

